import{_ as a,o as i,c as n,a1 as e}from"./chunks/framework.DJEphFjc.js";const r=JSON.parse('{"title":"Manjaro 黑屏只显示 loadkmap short read，实际是 NVIDIA 模块缺失","description":"从黑屏上的 loadkmap short read 入手，在 TTY 中确认并恢复缺失的 NVIDIA 内核模块。","frontmatter":{"title":"Manjaro 黑屏只显示 loadkmap short read，实际是 NVIDIA 模块缺失","description":"从黑屏上的 loadkmap short read 入手，在 TTY 中确认并恢复缺失的 NVIDIA 内核模块。","date":"2026-08-11T00:00:00.000Z","tags":["Manjaro","NVIDIA","KDE","Linux"],"sidebar":false},"headers":[],"relativePath":"zh/blog/2026-08-11-manjaro-nvidia-black-screen.md","filePath":"zh/blog/2026-08-11-manjaro-nvidia-black-screen.md"}'),l={name:"zh/blog/2026-08-11-manjaro-nvidia-black-screen.md"};function t(p,s,h,d,o,k){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="manjaro-黑屏只显示-loadkmap-short-read-实际是-nvidia-模块缺失" tabindex="-1">Manjaro 黑屏只显示 <code>loadkmap: short read</code>，实际是 NVIDIA 模块缺失 <a class="header-anchor" href="#manjaro-黑屏只显示-loadkmap-short-read-实际是-nvidia-模块缺失" aria-label="Permalink to &quot;Manjaro 黑屏只显示 \`loadkmap: short read\`，实际是 NVIDIA 模块缺失&quot;">​</a></h1><p><code>2026-08-11</code> · Manjaro · NVIDIA · KDE</p><p>电脑卡死并强制重启后，系统无法进入 KDE，黑屏上只显示：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loadkmap: short read</span></span></code></pre></div><h2 id="进入-tty-检查-sddm" tabindex="-1">进入 TTY 检查 SDDM <a class="header-anchor" href="#进入-tty-检查-sddm" aria-label="Permalink to &quot;进入 TTY 检查 SDDM&quot;">​</a></h2><p>按 <code>Ctrl + Alt + F2</code> 进入 TTY，检查 SDDM 状态和本次启动日志：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sddm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sddm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre></div><p>日志中出现：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NVIDIA: Failed to initialize the NVIDIA kernel module</span></span>
<span class="line"><span>no screens found</span></span>
<span class="line"><span>Could not start Display server on vt 2</span></span></code></pre></div><p>这说明 SDDM 无法启动图形界面，是因为 NVIDIA 内核模块初始化失败，而不是屏幕上那条 <code>loadkmap</code> 提示直接造成的。</p><h2 id="确认-nvidia-模块包被删除" tabindex="-1">确认 NVIDIA 模块包被删除 <a class="header-anchor" href="#确认-nvidia-模块包被删除" aria-label="Permalink to &quot;确认 NVIDIA 模块包被删除&quot;">​</a></h2><p>继续查询 pacman 日志：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;linux618-nvidia-open&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/pacman.log</span></span></code></pre></div><p>查询结果表明，之前一次批量清理孤立包时，<code>pacman -Qtdq</code> 输出的完整包名列表被直接交给 <code>pacman -Rns</code>，<code>linux618-nvidia-open</code> 也被一起删除。系统在下次启动 <code>linux618</code> 时找不到对应的 NVIDIA 模块，因此无法进入 KDE。</p><p>内核包不一定声明依赖 NVIDIA 驱动，pacman 也无法根据当前硬件判断一个孤立包是否仍有实际用途，所以不能未经检查就批量删除 <code>pacman -Qdt</code> 列出的所有软件包。</p><h2 id="恢复系统" tabindex="-1">恢复系统 <a class="header-anchor" href="#恢复系统" aria-label="Permalink to &quot;恢复系统&quot;">​</a></h2><p><code>linux618-nvidia-open</code> 是本机使用的包名。其他机器应先确认当前内核和已安装的 NVIDIA 模块包：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Qq</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^linux[0-9]+($|-nvidia(-open)?$)&#39;</span></span></code></pre></div><p>确认包名后，推荐使用普通的 <code>sudo</code> 命令恢复：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Syu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux618-nvidia-open</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-convert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-keymap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> us</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkinitcpio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><p>其中 <code>localectl</code> 没有加 <code>sudo</code>。本次操作时，执行 <code>sudo localectl --no-convert set-keymap us</code> 会报错，直接执行反而成功；当时没有保存完整错误内容，因此这里不进一步判断原因。</p><h2 id="本次实际使用的命令" tabindex="-1">本次实际使用的命令 <a class="header-anchor" href="#本次实际使用的命令" aria-label="Permalink to &quot;本次实际使用的命令&quot;">​</a></h2><p>当时 TTY 能正常显示 <code>sudo</code> 密码提示，但输入密码后按回车没有任何反应，命令始终没有继续执行。最后临时使用 <code>sudo -S</code> 从标准输入传入密码：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;当前用户密码&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pacman -Syu --noconfirm linux618-nvidia-open</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-convert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-keymap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> us</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;当前用户密码&gt;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mkinitcpio -P</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reboot</span></span></code></pre></div><p><code>sudo -S</code> 会从标准输入读取密码。</p><p>重启后能够正常进入 KDE 桌面。</p><h2 id="loadkmap-short-read-为什么会出现" tabindex="-1"><code>loadkmap: short read</code> 为什么会出现 <a class="header-anchor" href="#loadkmap-short-read-为什么会出现" aria-label="Permalink to &quot;\`loadkmap: short read\` 为什么会出现&quot;">​</a></h2><p>原来的 <code>/etc/vconsole.conf</code> 使用了本机不可用的键盘映射：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">KEYMAP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=cn</span></span></code></pre></div><p>执行以下命令会将它改为有效的 <code>us</code>，随后 <code>mkinitcpio -P</code> 会重新生成 initramfs：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-convert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-keymap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> us</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkinitcpio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span></span></code></pre></div><p>因此，<code>loadkmap: short read</code> 是黑屏上唯一可见的提示，但真正阻止 KDE 启动的是 NVIDIA 模块缺失。这两项都在本次恢复过程中得到处理。</p><h2 id="避免再次误删" tabindex="-1">避免再次误删 <a class="header-anchor" href="#避免再次误删" aria-label="Permalink to &quot;避免再次误删&quot;">​</a></h2><p>删除孤立包前，先逐项检查：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Qdt</span></span></code></pre></div><p>不要把它的完整输出未经检查直接传给 <code>pacman -Rns</code>。尤其要留意当前内核对应的 NVIDIA、headers、VirtualBox 等配套模块。</p><p>如果一个仍然需要的软件包被标记为孤立包，可以先将它标记为显式安装：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --asexplicit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux618-nvidia-open</span></span></code></pre></div><p>本次使用 <code>pacman -Syu linux618-nvidia-open</code> 重新安装后，该包也会被记为显式安装。</p>`,39)])])}const F=a(l,[["render",t]]);export{r as __pageData,F as default};
